def patch(raw,pairs):
    for old,new in pairs:
        old,new=old.encode(),new.encode()
        assert raw.count(old)==1,old
        raw=raw.replace(old,new,1)
    return raw
def transform(raw):
    return patch(patch(raw,JS_PATCHES),CSS_PATCHES)
